#!/usr/bin/env python3
"""Freeze Phase24 metrics and generate the self-contained final report."""
from __future__ import annotations

import csv
import hashlib
import json
import os
import subprocess
import tempfile
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "outputs/iclr27_phase24"
DOC = ROOT / "docs/iclr27_phase24/PHASE24_PROPOSAL_SELECTION_SOURCE_GENERALIZATION_COMPLETE_REPORT.md"


def atomic_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(prefix=f".{path.name}.", dir=str(path.parent))
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(value, f, indent=2, sort_keys=True); f.write("\n"); f.flush(); os.fsync(f.fileno())
        os.replace(tmp, path)
    finally:
        if os.path.exists(tmp): os.unlink(tmp)


def sha256(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for c in iter(lambda: f.read(1 << 20), b""): h.update(c)
    return h.hexdigest()


def load(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def main() -> None:
    stage0 = load(OUT / "audit/candidate_taxonomy_summary.json")
    stage0_records = load(OUT / "audit/candidate_taxonomy_76.json")["records"]
    stage1 = load(OUT / "metrics/stage1_unified_strategies.json")
    stage1_records = load(OUT / "audit/stage1_strategy_event_records.json")["records"]
    stage4 = load(OUT / "metrics/stage4_proposal_validation.json")
    stage4_records = load(OUT / "audit/stage4_setaware_event_records.json")["records"]
    p16_tax = {r["event_key"]: r for r in stage0_records if int(r["prefix"]) == 16}
    p16_s1 = {(r["event_key"], r["condition"]): r for r in stage1_records if int(r["prefix"]) == 16}
    p16_s4 = {r["event_key"]: r for r in stage4_records if int(r["prefix"]) == 16 and r["condition"] == "setaware_top20"}
    # A compact one-row-per-event table retains the complete denominator and
